console.log('Content script loaded for TL;DR extension.');

// Function to convert markdown text to HTML and display it
function displayMarkdownContent(markdownText, targetElement = null) {
  const container = window.createMarkdownContainer(markdownText);

  if (targetElement) {
    targetElement.appendChild(container);
  } else {
    // If no target specified, append to body
    document.body.appendChild(container);
  }

  return container;
}

// Export for use in other parts of the extension
window.displayMarkdownContent = displayMarkdownContent;

{
  "manifest_version": 3,
  "name": "TL;DR (Too Long; Didn't Read)",
  "version": "1.0",
  "description": "Summarize web pages with just one click.",
  "permissions": [
    "scripting",
    "storage",
    "contextMenus",
    "activeTab"
  ],
  "background": {
    "service_worker": "background.js"
  },
  "action": {
    "default_title": "TL;DR",
    "default_icon": {
      "16": "icons/icon16.png",
      "48": "icons/icon48.png",
      "128": "icons/icon128.png"
    }
  },
  "options_page": "options.html",
  "content_scripts": [
    {
      "matches": ["<all_urls>"],
      "js": ["markdown-utils.js", "content_script.js"]
    }
  ]
}

// Minimal markdown parser for basic formatting
window.parseMarkdown = (markdown) => {
  if (!markdown) return '';

  let html = markdown;

  // Normalize line endings
  html = html.replace(/\r\n/g, '\n');
  html = html.replace(/\r/g, '\n');

  // Replace headers (before other inline formatting)
  html = html.replace(/^#{3}\s+(.+)$/gm, '<h3>$1</h3>');
  html = html.replace(/^#{2}\s+(.+)$/gm, '<h2>$1</h2>');
  html = html.replace(/^#{1}\s+(.+)$/gm, '<h1>$1</h1>');

  // Replace bullet points and create lists
  const listItems = [];
  let inList = false;

  html = html.split('\n').map(line => {
    const listMatch = line.match(/^\s*[-*+]\s+(.+)$/);
    if (listMatch) {
      if (!inList) {
        inList = true;
        listItems.length = 0;
      }
      listItems.push(listMatch[1]);
      return null; // Mark for removal
    } else if (inList && line.trim() === '') {
      inList = false;
      const list = '<ul>' + listItems.map(item => `<li>${item}</li>`).join('') + '</ul>';
      listItems.length = 0;
      return list;
    } else if (inList) {
      inList = false;
      const list = '<ul>' + listItems.map(item => `<li>${item}</li>`).join('') + '</ul>';
      listItems.length = 0;
      return list + '\n' + line;
    }
    return line;
  }).filter(line => line !== null).join('\n');

  // If we ended while still in a list
  if (inList && listItems.length > 0) {
    html += '\n' + '<ul>' + listItems.map(item => `<li>${item}</li>`).join('') + '</ul>';
  }

  // Replace inline code (before other inline formatting to prevent conflicts)
  html = html.replace(/`([^`]+)`/g, '<code>$1</code>');

  // Replace bold
  html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

  // Replace italic (after bold to prevent conflicts)
  html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');

  // Replace double line breaks with paragraphs
  html = html.replace(/\n\s*\n/g, '</p><p>');

  // Wrap content in paragraphs if not already wrapped
  if (!html.startsWith('<')) {
    html = '<p>' + html;
  }
  if (!html.endsWith('>')) {
    html = html + '</p>';
  }

  // Clean up empty paragraphs and normalize spacing
  html = html.replace(/<p>\s*<\/p>/g, '');
  html = html.replace(/(<\/[^>]+>)\s*<p>/g, '$1');
  html = html.replace(/<p>\s*(<[^/][^>]*>)/g, '$1');

  // Replace remaining single line breaks
  html = html.replace(/\n/g, '<br>');

  return html;
};

// Helper function to create styled container for markdown content
window.createMarkdownContainer = (markdownText) => {
  const container = document.createElement('div');
  container.className = 'markdown-content';
  container.innerHTML = window.parseMarkdown(markdownText);

  // Add basic styles
  const style = document.createElement('style');
  style.textContent = `
    .markdown-content {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
      line-height: 1.5;
      color: #333;
      padding: 1rem;
    }
    .markdown-content p {
      margin: 0.5em 0;
    }
    .markdown-content ul {
      padding-left: 20px;
      margin: 0.5em 0;
      list-style-type: disc;
    }
    .markdown-content li {
      margin: 0.25em 0;
      line-height: 1.5;
    }
    .markdown-content li::marker {
      color: #3b82f6;
    }
    .markdown-content code {
      background-color: #f5f5f5;
      padding: 2px 4px;
      border-radius: 3px;
      font-family: monospace;
      font-size: 0.9em;
    }
    .markdown-content h1, .markdown-content h2, .markdown-content h3 {
      margin-top: 1em;
      margin-bottom: 0.5em;
      font-weight: 600;
    }
    .markdown-content h1 {
      font-size: 1.5em;
      color: #1a365d;
    }
    .markdown-content h2 {
      font-size: 1.3em;
      color: #2d3748;
    }
    .markdown-content h3 {
      font-size: 1.1em;
      color: #4a5568;
    }
    .markdown-content strong {
      color: #1a365d;
      font-weight: 600;
    }
    .markdown-content em {
      color: #4a5568;
      font-style: italic;
    }
  `;
  document.head.appendChild(style);

  return container;
};

document.addEventListener('DOMContentLoaded', function() {
  // Load saved settings
  chrome.storage.sync.get(
    {
      baseUrl: 'https://api.openai.com/v1',
      apiKey: '',
      prompt: 'Summarize this text in 3 key points. Format each point as a proper Markdown.',
      model: 'o3-mini',
      temperature: '0.8',
      top_p: '1.0',
      top_k: '0',
      frequency_penalty: '0',
      presence_penalty: '0',
      repetition_penalty: '0',
      max_tokens: null
    },
    function(items) {
      document.getElementById('baseUrl').value = items.baseUrl;
      document.getElementById('apiKey').value = items.apiKey;
      document.getElementById('prompt').value = items.prompt;
      document.getElementById('model').value = items.model;
      document.getElementById('temperature').value = items.temperature;
      document.getElementById('top_p').value = items.top_p;
      document.getElementById('top_k').value = items.top_k;
      document.getElementById('frequency_penalty').value = items.frequency_penalty;
      document.getElementById('presence_penalty').value = items.presence_penalty;
      document.getElementById('repetition_penalty').value = items.repetition_penalty;
      document.getElementById('max_tokens').value = items.max_tokens;
    }
  );

  // Handle API key visibility toggle
  const toggleVisibilityBtn = document.querySelector('.toggle-visibility');
  const apiKeyInput = document.getElementById('apiKey');

  toggleVisibilityBtn.addEventListener('click', function() {
    const isPassword = [REDACTED] === 'password';
    apiKeyInput.type = isPassword ? 'text' : 'password';
    toggleVisibilityBtn.textContent = isPassword ? '🔒' : '👁️';
    toggleVisibilityBtn.title = isPassword ? 'Hide API key' : 'Show API key';
  });

  // Handle settings save
  document.getElementById('options-form').addEventListener('submit', function(e) {
    e.preventDefault();
    const baseUrl = document.getElementById('baseUrl').value;
    const apiKey = [REDACTED]'apiKey').value;
    const prompt = document.getElementById('prompt').value;
    const model = document.getElementById('model').value;
    const temperature = document.getElementById('temperature').value;
    const top_p = document.getElementById('top_p').value;
    const top_k = document.getElementById('top_k').value;
    const frequency_penalty = document.getElementById('frequency_penalty').value;
    const presence_penalty = document.getElementById('presence_penalty').value;
    const repetition_penalty = document.getElementById('repetition_penalty').value;
    const max_tokens = document.getElementById('max_tokens').value;

    chrome.storage.sync.set({ baseUrl, apiKey, prompt, model, temperature, top_p, top_k, frequency_penalty, presence_penalty, repetition_penalty, max_tokens }, function() {
      // Show success message
      const successMessage = document.getElementById('success-message');
      successMessage.classList.add('show');

      // Hide message after 3 seconds
      setTimeout(() => {
        successMessage.classList.remove('show');
      }, 3000);
    });
  });

  // Add input animations
  const inputs = document.querySelectorAll('input, textarea');
  inputs.forEach(input => {
    input.addEventListener('focus', function() {
      this.parentElement.classList.add('focused');
    });
    input.addEventListener('blur', function() {
      this.parentElement.classList.remove('focused');
    });
  });

  // Handle reset buttons for advanced settings
  document.querySelectorAll('.reset-button').forEach(button => {
    button.addEventListener('click', function() {
      const defaultValue = this.dataset.default;
      const inputId = this.parentElement.getAttribute('for');
      const input = document.getElementById(inputId);
      input.value = defaultValue;
    });
  });
});

async function createOrUpdatePopup(tabId, summaryText) {
  function displayPopup(text) {
    const existingContent = document.getElementById('tldr-modal-content');
    if (existingContent) {
      existingContent.innerHTML = '<div class="markdown">' + window.parseMarkdown(text) + '</div>';
      return;
    }
    const style = document.createElement('style');
    style.textContent = `
      @keyframes modalFadeIn {
        from { opacity: 0; transform: scale(0.95); }
        to { opacity: 1; transform: scale(1); }
      }

      .tldr-modal-overlay {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0, 0, 0, 0.4);
        backdrop-filter: blur(4px);
        z-index: 9999;
        display: flex;
        align-items: center;
        justify-content: center;
        animation: modalFadeIn 0.2s ease-out;
      }

      .tldr-modal {
        background: #ffffff;
        border-radius: 16px;
        max-width: min(800px, 80%);
        max-height: 80vh;
        box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
        border: 1px solid rgba(0, 0, 0, 0.1);
        position: relative;
        display: flex;
        flex-direction: column;
        overflow: hidden;
      }

      .tldr-modal-content {
        flex: 1;
        overflow-y: auto;
        padding: 25px 25px 15px;
      }

      .tldr-modal-content::-webkit-scrollbar {
        width: 8px;
      }

      .tldr-modal-content::-webkit-scrollbar-track {
        background: transparent;
      }

      .tldr-modal-content::-webkit-scrollbar-thumb {
        background: #d1d5db;
        border-radius: 4px;
      }

      .tldr-modal-footer {
        padding: 15px 25px;
        background: linear-gradient(to bottom, rgba(255,255,255,0) 0%, rgba(249,250,251,1) 15%);
        border-top: 1px solid rgba(0,0,0,0.05);
        display: flex;
        justify-content: center;
        position: relative;
      }

      .tldr-modal-footer::before {
        content: '';
        position: absolute;
        top: -20px;
        left: 0;
        right: 0;
        height: 20px;
        background: linear-gradient(to bottom, rgba(255,255,255,0), #fff);
        pointer-events: none;
      }

      @keyframes modalFadeOut {
        from { opacity: 1; transform: scale(1); }
        to { opacity: 0; transform: scale(0.95); }
      }

      .tldr-modal-close {
        padding: 10px 32px;
        font-size: 14px;
        color: #fff;
        background: #3b82f6;
        border: none;
        border-radius: 20px;
        cursor: pointer;
        transition: all 0.2s ease;
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 6px;
        font-weight: 500;
      }

      .tldr-modal-close:hover {
        background: #2563eb;
        transform: translateY(-1px);
        box-shadow: 0 4px 12px rgba(59, 130, 246, 0.3);
      }

      .tldr-modal-close::before {
        content: "ESC";
        font-size: 10px;
        padding: 3px 5px;
        background: rgba(255, 255, 255, 0.2);
        border-radius: 4px;
        margin-right: 4px;
      }

      .markdown {
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
        white-space: pre-wrap;
        overflow-x: hidden;
        word-wrap: break-word;
        line-height: 1.6;
        margin: 0;
        padding: 15px 20px;
        color: #2c3e50;
        background: rgba(255, 255, 255, 0.8);
        border-radius: 12px;
        box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
      }

      .markdown ul {
        padding-left: 25px;
        margin: 10px 0;
      }

      .markdown li {
        margin: 8px 0;
        position: relative;
      }

      .markdown li::marker {
        color: #3b82f6;
      }

      .markdown strong {
        color: #1a365d;
        font-weight: 600;
      }

      .markdown em {
        color: #4a5568;
        font-style: italic;
      }

      .markdown code {
        background: #f1f5f9;
        padding: 2px 6px;
        border-radius: 4px;
        font-family: monospace;
        font-size: 0.9em;
        color: #2d3748;
      }

      @keyframes softPulse {
        0% { opacity: 0.5; transform: scale(0.98); }
        50% { opacity: 1; transform: scale(1); }
        100% { opacity: 0.5; transform: scale(0.98); }
      }

      .loading-state {
        text-align: center;
        padding: 40px;
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
        background: linear-gradient(135deg, #f0f9ff 0%, #e6f3ff 100%);
        border-radius: 12px;
      }

      .loading-text {
        font-size: 16px;
        font-weight: 500;
        color: #3b82f6;
        animation: softPulse 2s ease-in-out infinite;
        display: inline-block;
      }
    `;
    document.head.appendChild(style);

    const overlay = document.createElement('div');
    overlay.className = 'tldr-modal-overlay';
    overlay.id = 'tldr-modal-overlay';

    const modal = document.createElement('div');
    modal.className = 'tldr-modal';

    const modalContent = document.createElement('div');
    modalContent.className = 'tldr-modal-content';

    const content = document.createElement('div');
    content.id = 'tldr-modal-content';
    content.innerHTML = '<div class="markdown">' + window.parseMarkdown(text) + '</div>';

    const footer = document.createElement('div');
    footer.className = 'tldr-modal-footer';

    const closeButton = document.createElement('button');
    closeButton.className = 'tldr-modal-close';
    closeButton.textContent = 'Close';

    // Function to close modal with animation
    const closeModal = () => {
      overlay.style.animation = 'modalFadeOut 0.2s ease-in forwards';
      setTimeout(() => {
        overlay.remove();
        style.remove();
      }, 200);
    };

    // Close on button click
    closeButton.onclick = closeModal;

    // Close on overlay click (if clicked directly on overlay)
    overlay.onclick = (e) => {
      if (e.target === overlay) {
        closeModal();
      }
    };

    // Close on Escape key
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && document.getElementById('tldr-modal-overlay')) {
        closeModal();
      }
    });

    modalContent.appendChild(content);
    footer.appendChild(closeButton);
    modal.appendChild(modalContent);
    modal.appendChild(footer);
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
  }

  // First inject markdown-utils.js
  await chrome.scripting.executeScript({
    target: { tabId },
    files: ['markdown-utils.js']
  });

  // Then execute the display function
  await chrome.scripting.executeScript({
    target: { tabId },
    function: displayPopup,
    args: [summaryText]
  });
}

async function summarizeText(text, tabId) {
  chrome.storage.sync.get(
    { baseUrl: 'https://api.openai.com/v1', apiKey: '', prompt: 'Summarize this text in 3 key points. Format each point as a proper Markdown.', model: 'o3-mini' },
    async (items) => {
      if (!items.baseUrl || !items.apiKey) {
        chrome.scripting.executeScript({
          target: { tabId },
          func: () => alert('Please set Base URL and API Key in the extension options.')
        });
        return;
      }

      await createOrUpdatePopup(tabId, '<div class="loading-state"><span class="loading-text">Preparing summary</span></div>');

      let payload = {
        model: items.model,
        store: false,
        messages: [
          {
            role: "system",
            content: items.prompt || "Summarize this in 3 bullet points: "
          },
          {
            role: "user",
            content: text
          }
        ],
        temperature: parseFloat(items.temperature),
        top_p: parseFloat(items.top_p),
        top_k: parseInt(items.top_k),
        frequency_penalty: parseFloat(items.frequency_penalty),
        presence_penalty: parseFloat(items.presence_penalty),
        repetition_penalty: parseFloat(items.repetition_penalty)
      };
      if (items.max_tokens !== null && items.max_tokens !== '') {
        payload.max_tokens = parseInt(items.max_tokens);
      }

      try {
        const endpoint = items.baseUrl.endsWith('/chat/completions') ? items.baseUrl : items.baseUrl + '/chat/completions';
        const response = await fetch(endpoint, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + items.apiKey,
            'HTTP-Referer': 'https://github.com/sazonovanton/TLDR',
            'X-Title': 'TL;DR (Too Long; Didn\'t Read)'
          },
          body: JSON.stringify(payload)
        });
        let data;
        const rawText = await response.text();
        if(rawText.trim().startsWith("<")) {
          await createOrUpdatePopup(tabId, "API returned HTML response:\n" + rawText);
          return;
        }
        try {
          data = JSON.parse(rawText);
        } catch(parseError) {
          throw new Error("Invalid JSON response. " + rawText);
        }

        let summary = '';
        if (data && data.choices && data.choices.length > 0) {
          if (data.choices[0].message && data.choices[0].message.content) {
            summary = data.choices[0].message.content.trim();
          } else if (data.choices[0].text) {
            summary = data.choices[0].text.trim();
          }
        }
        if (!summary) {
          summary = rawText.trim() ? "Raw API response:\n" + rawText : "No summary returned.";
        }

        setTimeout(() => {
          createOrUpdatePopup(tabId, summary);
        }, 1000);
      } catch (error) {
        chrome.scripting.executeScript({
          target: { tabId },
          func: (errMsg) => alert('Error during summarization: ' + errMsg),
          args: [error.message]
        });
      }
    }
  );
}

chrome.contextMenus.removeAll(() => {
  chrome.contextMenus.create({
    id: 'summarize-selection',
    title: 'Summarize via TL;DR',
    contexts: ['selection']
  });
});

chrome.contextMenus.onClicked.addListener((info, tab) => {
  if (info.menuItemId === 'summarize-selection' && info.selectionText && tab.id) {
    summarizeText(info.selectionText, tab.id);
  }
});

chrome.action.onClicked.addListener(async (tab) => {
  if (!tab.id) return;

  try {
    if (tab.url?.startsWith('chrome://')) {
      await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: () => alert('Cannot summarize chrome:// pages')
      });
      return;
    }

    const results = await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: () => document.body.innerText
    });

    if (!results || !results[0].result) {
      await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: () => alert('Failed to extract text from the page.')
      });
      return;
    }

    const pageText = results[0].result;
    summarizeText(pageText, tab.id);
  } catch (error) {
    chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: (errMsg) => alert('Error: ' + errMsg),
      args: [error.message]
    });
  }
});
